func consoleRoute(domain, recordKey string) string {
	path := fmt.Sprintf("/console/%s", domain)
	if recordKey != "" {
		path += "?record_key=" + url.QueryEscape(recordKey)
		return path + "#/" + domain + "/" + url.PathEscape(recordKey)
	}
	return path + "#/" + domain
}

func queueURL(state string) string {
	values := url.Values{}
	if state != "" && state != "all" {
		values.Set("state", state)
	}
	path := "/console/queue"
	if encoded := values.Encode(); encoded != "" {
		path += "?" + encoded
	}
	return path + "#/queue"
}

func registryURL(surface SurfaceModel) string {
	values := url.Values{}
	if surface.Query != "" {
		values.Set("q", surface.Query)
	}
	if surface.Lifecycle != "" && surface.Lifecycle != "all" {
		values.Set("lifecycle", surface.Lifecycle)
	}
	path := "/console/agents"
	if encoded := values.Encode(); encoded != "" {
		path += "?" + encoded
	}
	return path + "#/agents"
}

func recordURL(surface SurfaceModel, key string) string {
	return detailRoute(surface, key)
}

func collectionRoute(surface SurfaceModel) string {
	if surface.CollectionURL != "" {
		return surface.CollectionURL
	}
	values := url.Values{}
	if surface.Query != "" {
		values.Set("q", surface.Query)
	}
	if surface.Domain == DomainQueue {
		if surface.QueueState != "" && surface.QueueState != "all" {
			values.Set("state", surface.QueueState)
		}
	} else if surface.Domain == DomainCredentials {
		if surface.Lifecycle != "" && surface.Lifecycle != "all" {
			values.Set("status", surface.Lifecycle)
		}
	} else if surface.Lifecycle != "" && surface.Lifecycle != "all" {
		values.Set("lifecycle", surface.Lifecycle)
	}
	path := "/console/" + surface.Domain
	if encoded := values.Encode(); encoded != "" {
		path += "?" + encoded
	}
	return path + "#/" + surface.Domain
}

func detailRoute(surface SurfaceModel, key string) string {
	base := collectionRoute(surface)
	if index := strings.IndexByte(base, '#'); index >= 0 {
		base = base[:index]
	}
	separator := "?"
	if strings.Contains(base, "?") {
		separator = "&"
	}
	return base + separator + "record_key=" + url.QueryEscape(key) + "#/" + surface.Domain + "/" + url.PathEscape(key)
}

func agentRevisionRoute(surface SurfaceModel, record *RecordModel) string {
	parsed, err := url.Parse(detailRoute(surface, record.Key))
	if err != nil || record.Agent == nil {
		return collectionRoute(surface)
	}
	query := parsed.Query()
	query.Set("revision", strconv.FormatUint(record.Agent.Revision, 10))
	parsed.RawQuery = query.Encode()
	return parsed.String()
}

func agentMark(label string) string {
	label = strings.TrimSpace(label)
	if label == "" {
		return "?"
	}
	return strings.ToUpper(string([]rune(label)[0]))
}

func fallbackTitle(title string) string {
	if title == "" {
		return "Fleet workspace"
	}
	return title
}
func documentTitle(model PageModel) string {
	if model.CharterImport && model.Authenticated {
		return "Agent registration · Aegis Console"
	}
	return "Aegis Console"
}
func currentPage(current bool) string {
	if current {
		return "page"
	}
	return "false"
}
func actionTitle(action ActionModel) string { return action.State + ": " + action.ReasonCode }
func hasBlockedAction(actions []ActionModel) bool {
	for _, action := range actions {
		if action.State != "ready" {
			return true
		}
	}
	return false
}
func actionTag(state string) string {
	if state == "denied" {
		return "tag-denied"
	}
	if state == "degraded_repair_required" {
		return "tag-degraded"
	}
	return "tag-locked"
}
func collectionSingular(domain string) string {
	if domain == DomainGraphs {
		return "graph"
	}
	return "Loop"
}
func countLabel(count int, singular string) string {
	suffix := "s"
	if count == 1 {
		suffix = ""
	}
	return fmt.Sprintf("%d %s%s", count, singular, suffix)
}
func graphRunURL(record *RecordModel) string {
	return "/console/graphs/run?graph=" + url.QueryEscape(record.Label) + "&revision=" + strings.TrimPrefix(record.Revision, "r") + "&digest=" + url.QueryEscape(record.Graph.Digest)
}
func stateHeading(state string) string {
	if state == "" {
		return "Unknown"
	}
	if state == "degraded_repair_required" {
		return "Repair required"
	}
	return strings.ToUpper(state[:1]) + state[1:]
}
func stateMessage(state string) string {
	switch state {
	case "empty":
		return "The authoritative collection is empty."
	case "denied":
		return "This collection read was denied. No count is asserted."
	case "unavailable":
		return "Fleet control is unavailable. This is not an empty collection."
	case "degraded_repair_required":
		return "Fleet state is degraded and requires repair. No count is asserted."
	case "loading":
		return "Loading authoritative state…"
	default:
		return "Fleet state could not be loaded or validated."
	}
}

